import{_ as i,o as s,c as a,a5 as t}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Empaquetage, signature et registres de plugins","description":"","frontmatter":{"title":"Empaquetage, signature et registres de plugins","docId":"developer.plugins.packaging-registry","translationKey":"developer.plugins.packaging-registry","locale":"fr","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b5c1b8dc63aafc5216467a00317c6670ac6744235abfc724fe372f3a28427ee8","translationRevision":"f559c829e08049810b7cfeef756f1668a775134b579b4ec228443252af3da023","order":280},"headers":[],"relativePath":"fr/developer/plugins/packaging-registry.md","filePath":"fr/developer/plugins/packaging-registry.md","lastUpdated":1794611623000}'),n={name:"fr/developer/plugins/packaging-registry.md"};function r(l,e,o,p,u,d){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="plugin-packaging-signing-and-registries" tabindex="-1">Empaquetage, signature et registres de plugins <a class="header-anchor" href="#plugin-packaging-signing-and-registries" aria-label="Permalink to &quot;Empaquetage, signature et registres de plugins {#plugin-packaging-signing-and-registries}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Distribuer un paquet dont les octets, l’autorité de l’éditeur et la compatibilité de l’hôte peuvent être vérifiés indépendamment. Commencez avec un plugin validé et une cible prise en charge. La signature nécessite des clés privées d’auteur conservées hors du dépôt ; la délégation racine du registre est une responsabilité distincte de l’opérateur.</p><h2 id="prepare-a-reviewable-archive" tabindex="-1">Préparer une archive à examiner <a class="header-anchor" href="#prepare-a-reviewable-archive" aria-label="Permalink to &quot;Préparer une archive à examiner {#prepare-a-reviewable-archive}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publish</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publisher</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys</span></span></code></pre></div><p><code>build</code> compile le paquet et crée des archives <code>.plugin</code>. L’entrée du manifeste, les ressources, langues, sorties d’interface et dépendances d’exécution pertinentes sont incluses avec <code>checksums.json</code>. Les compilations natives/processus nécessitent une ressource cible compatible ; les paquets uniquement JavaScript restent portables jusqu’à ce que des extensions natives ou fonctions de plateforme les contraignent.</p><p>Pour une archive compilée existante, utilisez des chemins de fichiers exacts plutôt qu’un joker non examiné :</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.key.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span></span></code></pre></div><p>Remplacez le nom de l’archive par la sortie réelle propre à la cible de compilation. La signature couvre les sommes de contrôle, qui couvrent les fichiers du paquet. Les clés publiques peuvent être partagées ; les fichiers de clés privées ne doivent entrer ni dans le contrôle de version ni dans les journaux.</p><h2 id="trust-and-update-policy" tabindex="-1">Confiance et politique de mise à jour <a class="header-anchor" href="#trust-and-update-policy" aria-label="Permalink to &quot;Confiance et politique de mise à jour {#trust-and-update-policy}&quot;">​</a></h2><p>Le protocole du registre statique possède une autorité signée par la racine et des clés déléguées d’index/éditeur. L’approbation de l’espace de noms d’un éditeur est distincte de l’intégrité du paquet, et une empreinte du catalogue Cloud ne remplace aucune des deux chaînes de signature. Le résolveur vérifie canal, moteur, schéma/protocole/ABI, environnement d’exécution et cible. Les versions retirées, révoquées ou incompatibles restent inéligibles même lorsque leur hachage correspond.</p><p>L’installation par l’hôte présente d’abord un examen. Les mises à jour automatiques nécessitent une politique autorisée, un paquet non épinglé, un éditeur signé compatible et aucune nouvelle autorité ; des permissions élargies exigent un examen. L’installation depuis le catalogue Cloud du produit est distincte de la création de registre statique de bas niveau, et les parcours produit ordinaires rejettent les URL de paquets distants arbitraires.</p><h2 id="expected-result-recovery-and-verification" tabindex="-1">Résultat attendu, récupération et vérification <a class="header-anchor" href="#expected-result-recovery-and-verification" aria-label="Permalink to &quot;Résultat attendu, récupération et vérification {#expected-result-recovery-and-verification}&quot;">​</a></h2><p>L’installateur peut vérifier les octets avant d’appliquer un paquet examiné et conserver un état de retour arrière/récupération. La préparation de développement échappe à la gestion de l’installateur. En cas d’échec de confiance, réparez la délégation ou les métadonnées de l’éditeur plutôt que d’utiliser normalement des options de contournement non signé. En cas de démarrage incertain, arrêtez le remplacement et résolvez le résultat conservé.</p><p>Utilisez <code>bun scripts/task.ts rust test -p tiktools-plugin-package --locked</code> et les tests du registre pour les fixtures hors ligne. Le <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-plugin-package/src" target="_blank" rel="noreferrer">vérificateur de paquets</a> et le <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-plugin-registry/src/model.rs" target="_blank" rel="noreferrer">modèle du registre</a> définissent les formats techniques ; l’infrastructure de publication nécessite une validation distincte de l’opérateur.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Interprétez le JSON de vérification, pas seulement le code de sortie. <code>verify</code> peut réussir avec <code>signature.status</code> égal à <code>unsigned</code> ou <code>untrusted</code>. N’acceptez que <code>verified</code> avec ID de paquet, éditeur et clé attendus, puis vérifiez la politique de distribution. Une clé locale <code>--trust</code> prouve cette signature locale, pas la délégation du registre ni le namespace. Les checksums seuls ne prouvent ni autorité ni confiance updater. L’automatisation ci-dessous doit échouer sur tout résultat inattendu.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verification.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;const r = await Bun.file(&quot;verification.json&quot;).json(); if (r.signature?.status !== &quot;verified&quot; || r.id !== &quot;acme.hello&quot; || r.signature.publisher !== &quot;acme&quot; || r.signature.keyId !== &quot;acme-1&quot;) throw new Error(&quot;Package trust did not match policy&quot;);&#39;</span></span></code></pre></div>`,18)])])}const g=i(n,[["render",r]]);export{h as __pageData,g as default};
